begin;
-- Block concurrent edits/submissions while deciding which snapshots are unanswered.
lock table public.class_assignment_responses, public.class_assignments, private.class_material_versions, public.weekly_sparks in share row exclusive mode;
create temporary table standalone_spark_patch on commit drop as
select value as p from jsonb_array_elements($standalone$[{"id":"technology_2026_g6_it_march_week1_core_vocabulary","before":[{"title":"Core Vocabulary","spark_text":"This week, Grade 6 connects its vocabulary to core first-trimester words for the Grade 6 summative vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Core Vocabulary that could help your Technology work this week?"}],"after":{"title":"Parts work together","spark_text":"A student types a sentence on a keyboard. The computer processes the input and shows the sentence on a screen. The keyboard provides input, the processor follows instructions, and the screen provides output. These connected parts work together as a computing system.","why_it_matters":"A system's result depends on parts performing connected jobs.","question":"What jobs do the keyboard and screen perform in this system?"}},{"id":"technology_2026_g7_it_march_week1_robotics_parts","before":[{"title":"Robotics Parts","spark_text":"This week, Grade 7 connects its vocabulary to core first-trimester words for the Grade 7 robotics vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics Parts that your team should test carefully?"}],"after":{"title":"Sense, decide, act","spark_text":"A robot detects an object in front of it. Its sensor provides information to a controller. The controller follows a programmed rule and tells the motors to stop. The sensor measures, the controller decides using the rule, and the motors carry out the action.","why_it_matters":"Different robot parts have different jobs in the same system.","question":"Which part detects the object, and which parts carry out the stop action?"}},{"id":"technology_2026_g8_it_march_week1_vector_graphics","before":[{"title":"Vector Graphics","spark_text":"This week, Grade 8 connects its vocabulary to core first-trimester words for the Grade 8 vector graphics vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Vector Graphics that could help your Technology work this week?"}],"after":{"title":"Resize a shape","spark_text":"A logo is drawn as vector shapes. A vector image describes shapes using paths and points, so the logo can be resized without turning those shapes into a larger grid of pixels. A small pixel-based image enlarged a great deal may show its individual pixels.","why_it_matters":"The type of image affects how well it suits different output sizes.","question":"Why could vector shapes be useful for a logo needed on both a small badge and a large poster?"}},{"id":"technology_2026_g9_it_march_week1_physical_computing","before":[{"title":"Physical Computing","spark_text":"This week, Grade 9 connects its vocabulary to core first-trimester words for the Grade 9 physical computing vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Physical Computing that could help your Technology work this week?"}],"after":{"title":"An input leads to an output","spark_text":"A small board has a button and a light display. Pressing the button gives the program an input. The program follows an instruction to show a heart on the display. The visible heart is an output. Input is information received; output is a result produced.","why_it_matters":"Following an input through to its output helps explain how a device works.","question":"What is the input in this example, and what output does it cause?"}},{"id":"technology_2026_g6_it_march_week2_sending_messages","before":[{"title":"Sending Messages","spark_text":"This week, Grade 6 connects its vocabulary to sending messages and packet order.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Sending Messages that could help your Technology work this week?"}],"after":{"title":"Pause before you send","spark_text":"Leo receives a message that says, 'Send your password now or your account will close.' The message tries to make him act quickly. A password is private information. Instead of replying or using the message's link, Leo can open the service through its usual app and ask a trusted adult for help.","why_it_matters":"An urgent message can pressure someone into sharing private information.","question":"What should Leo do instead of sending his password? Explain why."}},{"id":"technology_2026_g7_it_march_week2_robotics_mblock_workspace","before":[{"title":"Robotics: mBlock Workspace","spark_text":"This week, Grade 7 connects its vocabulary to mBlock tools and first scripts.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: mBlock Workspace that your team should test carefully?"}],"after":{"title":"Sense, decide, act","spark_text":"A robot detects an object in front of it. Its sensor provides information to a controller. The controller follows a programmed rule and tells the motors to stop. The sensor measures, the controller decides using the rule, and the motors carry out the action.","why_it_matters":"Different robot parts have different jobs in the same system.","question":"Which part detects the object, and which parts carry out the stop action?"}},{"id":"technology_2026_g8_it_march_week2_alignment_and_grouping","before":[{"title":"Alignment and Grouping","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Alignment and Grouping that could help your Technology work this week?"}],"after":{"title":"Help the reader see the order","spark_text":"A poster has a title and three text blocks. Their left edges start at different places, making the page feel scattered. The designer aligns the left edges and groups each heading with its paragraph. Alignment and grouping help readers see which elements belong together.","why_it_matters":"Layout can make a message easier to follow without adding more words.","question":"Which two layout changes help organise this poster?"}},{"id":"technology_2026_g9_it_march_week2_blink_and_signals","before":[{"title":"Blink and Signals","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Blink and Signals that could help your Technology work this week?"}],"after":{"title":"Make a visible signal","spark_text":"A small board has an LED that a program can turn on and off. An LED is a light-emitting diode. A program turns it on for one second, then off for one second, and repeats. The changing light is an output that a person can see.","why_it_matters":"A light can communicate that a device is running or has changed state.","question":"What visible pattern does this program produce?"}},{"id":"technology_2026_g6_it_march_week3_working_together_online","before":[{"title":"Working Together Online","spark_text":"This week, Grade 6 connects its vocabulary to online collaboration and shared work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Working Together Online that could help your Technology work this week?"}],"after":{"title":"Make the next step clear","spark_text":"Two students edit the same shared poster. Both replace the title at the same time and lose track of the intended wording. They agree that one will edit the title while the other checks the image, then review the changes together. Collaboration needs clear responsibilities as well as shared access.","why_it_matters":"An agreed plan can prevent people from undoing each other's work.","question":"How does dividing these two tasks help the students work together?"}},{"id":"technology_2026_g7_it_march_week3_robotics_movement_commands","before":[{"title":"Robotics: Movement Commands","spark_text":"This week, Grade 7 connects its vocabulary to basic robot movement.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Movement Commands that your team should test carefully?"}],"after":{"title":"Instructions become movement","spark_text":"A wheeled robot uses motors to turn its wheels. Its program tells both motors to move forward for two seconds and then stop. A motor is an output device because it produces an action. Changing the instruction can change how the robot moves.","why_it_matters":"Movement depends on both the program and the robot's outputs.","question":"What is the output in this example, and which instruction controls how long it moves?"}},{"id":"technology_2026_g8_it_march_week3_campaign_graphics","before":[{"title":"Campaign Graphics","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Campaign Graphics that could help your Technology work this week?"}],"after":{"title":"Make the signs recognisable","spark_text":"A school club uses the same name, simple logo and two colours on its poster and invitation. These repeated choices help people recognise that the two items belong to the same club. A visual identity is a consistent set of design choices associated with a group or organisation.","why_it_matters":"Consistent design helps an audience recognise related information.","question":"Which repeated choices connect the poster with the invitation?"}},{"id":"technology_2026_g9_it_march_week3_lab_routine","before":[{"title":"Lab Routine","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Lab Routine that could help your Technology work this week?"}],"after":{"title":"Leave the workspace ready","spark_text":"At the end of a robotics lesson, a pair stops the robot, follows the teacher's power-down instructions, returns the parts to labelled spaces and saves its program. A routine is a repeated sequence of actions. Following the same agreed steps makes missing files or parts easier to notice.","why_it_matters":"A clear routine helps the next person find a usable workspace.","question":"Which action protects the students' code, and which action helps keep the parts organised?"}},{"id":"technology_2026_g6_it_march_week4_safe_communication_and_websites","before":[{"title":"Safe Communication and Websites","spark_text":"This week, Grade 6 connects its vocabulary to safe communication and basic website planning.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Safe Communication and Websites that could help your Technology work this week?"}],"after":{"title":"Ask before posting","spark_text":"Nora takes a photo of her friend during lunch. She wants to post it where everyone can see it. Her friend has not agreed. Being in a photo does not mean someone has agreed to have it shared. Nora can ask first and respect a 'no.'","why_it_matters":"A photo can reveal information about someone who did not choose to share it.","question":"What should Nora do before posting the photo? Explain your reason."}},{"id":"technology_2026_g7_it_march_week4_robotics_robot_systems","before":[{"title":"Robotics: Robot Systems","spark_text":"This week, Grade 7 connects its vocabulary to robots as systems and debugging.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Robot Systems that your team should test carefully?"}],"after":{"title":"Sense, decide, act","spark_text":"A robot detects an object in front of it. Its sensor provides information to a controller. The controller follows a programmed rule and tells the motors to stop. The sensor measures, the controller decides using the rule, and the motors carry out the action.","why_it_matters":"Different robot parts have different jobs in the same system.","question":"Which part detects the object, and which parts carry out the stop action?"}},{"id":"technology_2026_g8_it_march_week4_svg_and_markup","before":[{"title":"SVG and Markup","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from SVG and Markup that could help your Technology work this week?"}],"after":{"title":"Resize a shape","spark_text":"A logo is drawn as vector shapes. A vector image describes shapes using paths and points, so the logo can be resized without turning those shapes into a larger grid of pixels. A small pixel-based image enlarged a great deal may show its individual pixels.","why_it_matters":"The type of image affects how well it suits different output sizes.","question":"Why could vector shapes be useful for a logo needed on both a small badge and a large poster?"}},{"id":"technology_2026_g9_it_march_week4_button_toggle","before":[{"title":"Button Toggle","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Button Toggle that could help your Technology work this week?"}],"after":{"title":"A press changes the state","spark_text":"A device starts with its light off. Each new button press changes the light to the opposite state: off becomes on, and on becomes off. This is a toggle. After two presses, the light is off again. The program must remember its current state between presses.","why_it_matters":"Remembering state lets the same input have the correct next effect.","question":"Starting with the light off, what state should it have after three presses? Explain."}},{"id":"technology_2026_g6_it_april_week1_copyright_and_images","before":[{"title":"Copyright and Images","spark_text":"This week, Grade 6 connects its vocabulary to choosing safe images and giving credit.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Copyright and Images that could help your Technology work this week?"}],"after":{"title":"Finding an image is not permission","spark_text":"Sara finds a picture online for a poster. The page says the image is available under a licence that requires credit. A licence explains how a work may be used. Sara reads those conditions and includes the creator's name and the source when she uses the image.","why_it_matters":"The person who made an image may set conditions for using it.","question":"What must Sara check before using the image, and what credit is required in this example?"}},{"id":"technology_2026_g7_it_april_week5_robotics_calibration","before":[{"title":"Robotics: Calibration","spark_text":"This week, Grade 7 connects its vocabulary to speed, time, distance, and accuracy.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Calibration that your team should test carefully?"}],"after":{"title":"Make the turns more accurate","spark_text":"A robot is programmed to turn 90 degrees, but repeated tests show turns of about 100 degrees. The team adjusts its turning setting and tests again from the same start position. Calibration means adjusting a system using measurements so its results are closer to the intended value.","why_it_matters":"Measurements give a better reason for an adjustment than guessing.","question":"What measurement shows that an adjustment is needed, and what should the team test afterward?"}},{"id":"technology_2026_g8_it_april_week5_computing_systems","before":[{"title":"Computing Systems","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Computing Systems that could help your Technology work this week?"}],"after":{"title":"Parts work together","spark_text":"A student types a sentence on a keyboard. The computer processes the input and shows the sentence on a screen. The keyboard provides input, the processor follows instructions, and the screen provides output. These connected parts work together as a computing system.","why_it_matters":"A system's result depends on parts performing connected jobs.","question":"What jobs do the keyboard and screen perform in this system?"}},{"id":"technology_2026_g9_it_april_week5_serial_and_analog","before":[{"title":"Serial and Analog","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Serial and Analog that could help your Technology work this week?"}],"after":{"title":"See the values a device sends","spark_text":"A board reads a sensor value of 35 and sends the text 'Light: 35' to a connected computer. Serial communication sends data in a sequence. Displaying the received values lets the programmer compare the sensor readings with the device's surroundings.","why_it_matters":"Visible readings help a programmer inspect what the device is sensing.","question":"What information does 'Light: 35' give the person testing this device?"}},{"id":"technology_2026_g7_it_april_week6_robotics_route_planning","before":[{"title":"Robotics: Route Planning","spark_text":"This week, Grade 7 connects its vocabulary to planning and improving robot routes.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Route Planning that your team should test carefully?"}],"after":{"title":"Plan before the robot moves","spark_text":"A floor grid has a start square and a finish square. The planned route is two squares forward, a right turn, then one square forward. A route is an ordered path. The team draws that path first so it can compare the robot's movement with the plan.","why_it_matters":"A clear route lets a team spot where a movement differs from the plan.","question":"What should the robot do immediately after the right turn?"}},{"id":"technology_2026_g8_it_april_week6_ai_and_responsible_remix","before":[{"title":"AI and Responsible Remix","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from AI and Responsible Remix that could help your Technology work this week?"}],"after":{"title":"Check before using an AI answer","spark_text":"An AI tool writes that a club meeting is on Friday. The school's notice says Thursday. AI-generated text can contain mistakes. Lina checks the claim against the notice and uses Thursday. She also tells her group that she used an AI tool to help draft the message.","why_it_matters":"A fluent answer still needs evidence and responsible use.","question":"Which date should Lina use, and why should she check the AI-generated claim?"}},{"id":"technology_2026_g9_it_april_week6_sensor_and_rgb","before":[{"title":"Sensor and RGB","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Sensor and RGB that your team should test carefully?"}],"after":{"title":"Mix three light channels","spark_text":"An RGB light combines red, green and blue light. In this example, each channel can be set from 0 to 255. The setting red 255, green 0, blue 0 uses only red. Changing the three channel values changes the combined light.","why_it_matters":"Separate channel values let a program control the colour of a light.","question":"Which channel is active in the setting 255, 0, 0, and which two are off?"}},{"id":"technology_2026_g6_it_april_week2_web_page_structure","before":[{"title":"Web Page Structure","spark_text":"This week, Grade 6 connects its vocabulary to organizing and previewing a web page.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Web Page Structure that could help your Technology work this week?"}],"after":{"title":"Structure the page","spark_text":"A web page has a heading, a paragraph and a link. HTML marks the structure and meaning of these parts. CSS controls presentation such as text colour and spacing. Changing the paragraph's colour in CSS changes its appearance without turning it into a different kind of element.","why_it_matters":"Separating structure from presentation makes page changes easier to manage.","question":"Which language would you use to change text colour, and which gives the paragraph its structure?"}},{"id":"technology_2026_g7_it_april_week7_feedback_signals","before":[{"title":"Feedback Signals","spark_text":"This week, Grade 7 connects its vocabulary to lights, sound, and robot state signals.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Feedback Signals that could help your Technology work this week?"}],"after":{"title":"Make a visible signal","spark_text":"A small board has an LED that a program can turn on and off. An LED is a light-emitting diode. A program turns it on for one second, then off for one second, and repeats. The changing light is an output that a person can see.","why_it_matters":"A light can communicate that a device is running or has changed state.","question":"What visible pattern does this program produce?"}},{"id":"technology_2026_g8_it_april_week7_html_and_css","before":[{"title":"HTML and CSS","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from HTML and CSS that could help your Technology work this week?"}],"after":{"title":"Structure the page","spark_text":"A web page has a heading, a paragraph and a link. HTML marks the structure and meaning of these parts. CSS controls presentation such as text colour and spacing. Changing the paragraph's colour in CSS changes its appearance without turning it into a different kind of element.","why_it_matters":"Separating structure from presentation makes page changes easier to manage.","question":"Which language would you use to change text colour, and which gives the paragraph its structure?"}},{"id":"technology_2026_g9_it_april_week7_led_teamwork","before":[{"title":"LED Teamwork","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from LED Teamwork that could help your Technology work this week?"}],"after":{"title":"Make a visible signal","spark_text":"A small board has an LED that a program can turn on and off. An LED is a light-emitting diode. A program turns it on for one second, then off for one second, and repeats. The changing light is an output that a person can see.","why_it_matters":"A light can communicate that a device is running or has changed state.","question":"What visible pattern does this program produce?"}},{"id":"technology_2026_g6_it_april_week3_links_and_navigation","before":[{"title":"Links and Navigation","spark_text":"This week, Grade 6 connects its vocabulary to moving around a website and testing links.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Links and Navigation that could help your Technology work this week?"}],"after":{"title":"Tell people where the link goes","spark_text":"A page has two links, both labelled 'Click here'. One opens club rules and the other opens a registration form. A link connects a reader to another location. Labels such as 'Read club rules' and 'Open registration form' describe the destination before the reader follows it.","why_it_matters":"Clear link labels help people choose the correct destination.","question":"Why are the two descriptive labels more useful than 'Click here'?"}},{"id":"technology_2026_g7_it_april_week8_robotics_sensor_conditions","before":[{"title":"Robotics: Sensor Conditions","spark_text":"This week, Grade 7 connects its vocabulary to ultrasonic sensors and if/else reactions.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Sensor Conditions that your team should test carefully?"}],"after":{"title":"Choose an action with a condition","spark_text":"A game checks whether the player has at least 10 points. If the condition is true, it opens the next level. If the condition is false, the player stays in the current level. A condition is a statement a program can check as true or false.","why_it_matters":"Conditions let a program choose between actions.","question":"What happens at 8 points and at 10 points? Use the rule in the reading."}},{"id":"technology_2026_g8_it_april_week8_search_and_portfolio","before":[{"title":"Search and Portfolio","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Search and Portfolio that could help your Technology work this week?"}],"after":{"title":"A claim needs evidence","spark_text":"A post claims that the school will close tomorrow, but it gives no source. Omar checks the school's official notice and finds that classes will continue. A source is where information comes from. Comparing the post with an official notice helps him decide whether to share it.","why_it_matters":"Checking the original source can stop an unsupported claim from spreading.","question":"Which source should Omar rely on here, and what evidence supports his choice?"}},{"id":"technology_2026_g9_it_april_week8_state_prototype","before":[{"title":"State Prototype","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from State Prototype that could help your Technology work this week?"}],"after":{"title":"A press changes the state","spark_text":"A device starts with its light off. Each new button press changes the light to the opposite state: off becomes on, and on becomes off. This is a toggle. After two presses, the light is off again. The program must remember its current state between presses.","why_it_matters":"Remembering state lets the same input have the correct next effect.","question":"Starting with the light off, what state should it have after three presses? Explain."}},{"id":"technology_2026_g6_it_april_week4_scratch_variables","before":[{"title":"Scratch Variables","spark_text":"This week, Grade 6 connects its vocabulary to a Scratch score challenge.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Scratch Variables that could help your Technology work this week?"}],"after":{"title":"Remember the score","spark_text":"A game starts with a score of 0. Each time the player collects a star, the program adds 1 to score. A variable is a named value that a program can change. After three stars, score holds 3, so the game can display the current result.","why_it_matters":"A variable lets a program remember information while it runs.","question":"What value should score hold after five stars, and why does the game need to remember it?"}},{"id":"technology_2026_g6_it_may_week1_internet_day","before":[{"title":"Internet Day","spark_text":"This week, Grade 6 connects its vocabulary to responsible Internet Day choices and campaign messages.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Internet Day that could help your Technology work this week?"}],"after":{"title":"Which details should stay private?","spark_text":"A game profile asks Ana to choose a display name. Another player asks for her home address and password. A display name can identify her in the game without revealing her address. She does not need to share her address or password to play with someone.","why_it_matters":"Sharing fewer personal details gives strangers less information about you.","question":"Which two details should Ana keep private, and why?"}},{"id":"technology_2026_g7_it_may_week9_robotics_maze_planning","before":[{"title":"Robotics: Maze Planning","spark_text":"This week, Grade 7 connects its vocabulary to maze route planning.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Maze Planning that your team should test carefully?"}],"after":{"title":"Plan before the robot moves","spark_text":"A floor grid has a start square and a finish square. The planned route is two squares forward, a right turn, then one square forward. A route is an ordered path. The team draws that path first so it can compare the robot's movement with the plan.","why_it_matters":"A clear route lets a team spot where a movement differs from the plan.","question":"What should the robot do immediately after the right turn?"}},{"id":"technology_2026_g8_it_may_week9_portfolio_planning","before":[{"title":"Portfolio Planning","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Portfolio Planning that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g9_it_may_week9_robot_design","before":[{"title":"Robot Design","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robot Design that your team should test carefully?"}],"after":{"title":"Sense, decide, act","spark_text":"A robot detects an object in front of it. Its sensor provides information to a controller. The controller follows a programmed rule and tells the motors to stop. The sensor measures, the controller decides using the rule, and the motors carry out the action.","why_it_matters":"Different robot parts have different jobs in the same system.","question":"Which part detects the object, and which parts carry out the stop action?"}},{"id":"technology_2026_g7_it_may_week10_project_plan","before":[{"title":"Project Plan","spark_text":"This week, Grade 7 connects its vocabulary to planning the mBot maze project.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Project Plan that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g8_it_may_week10_homepage_and_media","before":[{"title":"Homepage and Media","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Homepage and Media that could help your Technology work this week?"}],"after":{"title":"Use media to support the message","spark_text":"An online guide explains how to pack a school bag. It includes a short paragraph and a photo showing the arranged items. The photo supports the explanation. An unrelated animated image would use attention without showing the reader how to complete the task.","why_it_matters":"Useful media helps the audience understand the intended message.","question":"Why does the packing photo help this guide more than an unrelated animation?"}},{"id":"technology_2026_g9_it_may_week10_project_build","before":[{"title":"Project Build","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Project Build that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g6_it_may_week2_recycling_and_e_waste","before":[{"title":"Recycling and E-Waste","spark_text":"This week, Grade 6 connects its vocabulary to responsible technology waste choices.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Recycling and E-Waste that could help your Technology work this week?"}],"after":{"title":"Think before throwing a device away","spark_text":"A school has an old tablet that no longer holds a charge. A technician checks whether it can be repaired. If it cannot be reused, the school sends it to an appropriate electronics collection service. Electronic waste includes discarded electrical and electronic devices.","why_it_matters":"Repair, reuse and appropriate collection can reduce what is thrown away.","question":"What should the school check before deciding that the tablet must be discarded?"}},{"id":"technology_2026_g7_it_may_week11_testing_and_debugging","before":[{"title":"Testing and Debugging","spark_text":"This week, Grade 7 connects its vocabulary to debugging and documenting robot performance.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Testing and Debugging that could help your Technology work this week?"}],"after":{"title":"Find the cause of the wrong result","spark_text":"A game should add one point for each star, but it adds two. Eva checks the scoring instructions and finds two 'add 1' commands running for the same star. She removes one and tests again. Debugging means finding and fixing the cause of a problem.","why_it_matters":"A useful fix addresses the cause and is checked with another test.","question":"What caused the extra point, and how can Eva check that her fix worked?"}},{"id":"technology_2026_g8_it_may_week11_testing_and_revision","before":[{"title":"Testing and Revision","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Testing and Revision that could help your Technology work this week?"}],"after":{"title":"Explain what changed","spark_text":"A student compares two versions of a poster. In the first, small text was hard to read. In the second, the text is larger, and three classmates can read it from the same distance. A reflection explains a change, its reason and the evidence of its effect.","why_it_matters":"Specific evidence makes a reflection more useful than simply saying 'It is better.'","question":"Which change did the student make, and what evidence suggests it helped?"}},{"id":"technology_2026_g9_it_may_week11_reliability","before":[{"title":"Reliability","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Reliability that could help your Technology work this week?"}],"after":{"title":"One successful run is not enough","spark_text":"A robot reaches the finish once. On the next two runs, it stops early. A reliable system works consistently under the same conditions. The team keeps the route and starting point the same and repeats the test after making a change.","why_it_matters":"Repeated tests help show whether a result is consistent.","question":"Why does one successful run not prove that this robot is reliable?"}},{"id":"technology_2026_g6_it_may_week3_awareness_product","before":[{"title":"Awareness Product","spark_text":"This week, Grade 6 connects its vocabulary to planning and presenting an awareness product.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Awareness Product that could help your Technology work this week?"}],"after":{"title":"Use media to support the message","spark_text":"An online guide explains how to pack a school bag. It includes a short paragraph and a photo showing the arranged items. The photo supports the explanation. An unrelated animated image would use attention without showing the reader how to complete the task.","why_it_matters":"Useful media helps the audience understand the intended message.","question":"Why does the packing photo help this guide more than an unrelated animation?"}},{"id":"technology_2026_g7_it_may_week12_presentation","before":[{"title":"Presentation","spark_text":"This week, Grade 7 connects its vocabulary to presenting the maze solution.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Presentation that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g8_it_may_week12_presentation","before":[{"title":"Presentation","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Presentation that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g9_it_may_week12_demonstration","before":[{"title":"Demonstration","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Demonstration that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g8_it_may_week13_archive_and_reflection","before":[{"title":"Archive and Reflection","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 first-trimester work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Archive and Reflection that could help your Technology work this week?"}],"after":{"title":"Explain what changed","spark_text":"A student compares two versions of a poster. In the first, small text was hard to read. In the second, the text is larger, and three classmates can read it from the same distance. A reflection explains a change, its reason and the evidence of its effect.","why_it_matters":"Specific evidence makes a reflection more useful than simply saying 'It is better.'","question":"Which change did the student make, and what evidence suggests it helped?"}},{"id":"technology_2026_g9_it_may_week13_archive","before":[{"title":"Archive","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 first-trimester physical computing work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Archive that could help your Technology work this week?"}],"after":{"title":"Keep a useful record","spark_text":"A team finishes a project and saves its final file, source images and a short note explaining how to open it. An archive is an organised collection kept for later use. Clear names help the team distinguish the final version from earlier drafts.","why_it_matters":"An organised archive helps someone find and understand work later.","question":"Which files and instructions should this team keep so another person can reopen the project?"}},{"id":"technology_2026_g6_iit_june_week1_robotics_vocabulary","before":[{"title":"Robotics Vocabulary","spark_text":"This week, Grade 6 connects its vocabulary to core second-trimester words for the Grade 6 robotics summative vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics Vocabulary that your team should test carefully?"}],"after":{"title":"Sense, decide, act","spark_text":"A robot detects an object in front of it. Its sensor provides information to a controller. The controller follows a programmed rule and tells the motors to stop. The sensor measures, the controller decides using the rule, and the motors carry out the action.","why_it_matters":"Different robot parts have different jobs in the same system.","question":"Which part detects the object, and which parts carry out the stop action?"}},{"id":"technology_2026_g7_iit_june_week1_poster_and_media_design","before":[{"title":"Poster and Media Design","spark_text":"This week, Grade 7 connects its vocabulary to core second-trimester words for the Grade 7 poster and media design vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Poster and Media Design that could help your Technology work this week?"}],"after":{"title":"Make the signs recognisable","spark_text":"A school club uses the same name, simple logo and two colours on its poster and invitation. These repeated choices help people recognise that the two items belong to the same club. A visual identity is a consistent set of design choices associated with a group or organisation.","why_it_matters":"Consistent design helps an audience recognise related information.","question":"Which repeated choices connect the poster with the invitation?"}},{"id":"technology_2026_g8_iit_june_week1_arduino_basics","before":[{"title":"Arduino Basics","spark_text":"This week, Grade 8 connects its vocabulary to core second-trimester words for the Grade 8 Arduino vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Arduino Basics that could help your Technology work this week?"}],"after":{"title":"An input leads to an output","spark_text":"A small board has a button and a light display. Pressing the button gives the program an input. The program follows an instruction to show a heart on the display. The visible heart is an output. Input is information received; output is a result produced.","why_it_matters":"Following an input through to its output helps explain how a device works.","question":"What is the input in this example, and what output does it cause?"}},{"id":"technology_2026_g9_iit_june_week1_python_and_data","before":[{"title":"Python and Data","spark_text":"This week, Grade 9 connects its vocabulary to core second-trimester words for the Grade 9 Python and data vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data that could help your work this week?"}],"after":{"title":"Remember the score","spark_text":"A game starts with a score of 0. Each time the player collects a star, the program adds 1 to score. A variable is a named value that a program can change. After three stars, score holds 3, so the game can display the current result.","why_it_matters":"A variable lets a program remember information while it runs.","question":"What value should score hold after five stars, and why does the game need to remember it?"}},{"id":"technology_2026_g6_iit_june_week2_robotics_movement_instructions","before":[{"title":"Robotics: Movement Instructions","spark_text":"This week, Grade 6 connects its vocabulary to movement instructions and timing.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Movement Instructions that your team should test carefully?"}],"after":{"title":"Instructions become movement","spark_text":"A wheeled robot uses motors to turn its wheels. Its program tells both motors to move forward for two seconds and then stop. A motor is an output device because it produces an action. Changing the instruction can change how the robot moves.","why_it_matters":"Movement depends on both the program and the robot's outputs.","question":"What is the output in this example, and which instruction controls how long it moves?"}},{"id":"technology_2026_g7_iit_june_week2_branding","before":[{"title":"Branding","spark_text":"This week, Grade 7 connects its vocabulary to branding and consistent design.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Branding that could help your Technology work this week?"}],"after":{"title":"Make the signs recognisable","spark_text":"A school club uses the same name, simple logo and two colours on its poster and invitation. These repeated choices help people recognise that the two items belong to the same club. A visual identity is a consistent set of design choices associated with a group or organisation.","why_it_matters":"Consistent design helps an audience recognise related information.","question":"Which repeated choices connect the poster with the invitation?"}},{"id":"technology_2026_g8_iit_june_week2_led_and_button","before":[{"title":"LED and Button","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from LED and Button that could help your Technology work this week?"}],"after":{"title":"A press changes the state","spark_text":"A device starts with its light off. Each new button press changes the light to the opposite state: off becomes on, and on becomes off. This is a toggle. After two presses, the light is off again. The program must remember its current state between presses.","why_it_matters":"Remembering state lets the same input have the correct next effect.","question":"Starting with the light off, what state should it have after three presses? Explain."}},{"id":"technology_2026_g9_iit_june_week2_python_and_data_list_methods","before":[{"title":"Python and Data: List Methods","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: List Methods that could help your work this week?"}],"after":{"title":"Keep several values together","spark_text":"A program stores three club names in a list: chess, art and music. A list keeps several items in an order. Instead of creating a separate variable for every club, the program can work through the list. Adding drama gives it a fourth item.","why_it_matters":"A list helps organise several related values.","question":"How many items are in the list after drama is added, and what makes a list useful here?"}},{"id":"technology_2026_g6_iit_june_week3_debugging_paths","before":[{"title":"Debugging Paths","spark_text":"This week, Grade 6 connects its vocabulary to testing, debugging, and improving robot paths.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Debugging Paths that could help your Technology work this week?"}],"after":{"title":"Find the cause of the wrong result","spark_text":"A game should add one point for each star, but it adds two. Eva checks the scoring instructions and finds two 'add 1' commands running for the same star. She removes one and tests again. Debugging means finding and fixing the cause of a problem.","why_it_matters":"A useful fix addresses the cause and is checked with another test.","question":"What caused the extra point, and how can Eva check that her fix worked?"}},{"id":"technology_2026_g7_iit_july_week3_scratch_intro","before":[{"title":"Scratch Intro","spark_text":"This week, Grade 7 connects its vocabulary to Scratch sequences and events.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Scratch Intro that could help your Technology work this week?"}],"after":{"title":"What starts the action?","spark_text":"An app has a button labelled Play. Pressing that button is an event. The app responds by playing a sound. The button itself is not the sound; it is the control that triggers the action. Without the event, this sound does not start.","why_it_matters":"An event connects something the user does with a response from the program.","question":"What is the event in this example, and what action does it trigger?"}},{"id":"technology_2026_g8_iit_june_week3_state_and_serial","before":[{"title":"State and Serial","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from State and Serial that could help your Technology work this week?"}],"after":{"title":"A press changes the state","spark_text":"A device starts with its light off. Each new button press changes the light to the opposite state: off becomes on, and on becomes off. This is a toggle. After two presses, the light is off again. The program must remember its current state between presses.","why_it_matters":"Remembering state lets the same input have the correct next effect.","question":"Starting with the light off, what state should it have after three presses? Explain."}},{"id":"technology_2026_g9_iit_june_week3_python_and_data_loops_and_strings","before":[{"title":"Python and Data: Loops and Strings","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Loops and Strings that could help your work this week?"}],"after":{"title":"Text and numbers behave differently","spark_text":"A program can store the number 12 or the text '12'. Text is stored as a string. Adding the numbers 12 and 3 gives 15. Joining the strings '12' and '3' gives the text '123'. The stored type affects which operation makes sense.","why_it_matters":"Checking a value's type helps prevent unexpected results.","question":"Why are 15 and '123' different results in this example?"}},{"id":"technology_2026_g6_iit_june_week4_robotics_robot_outputs","before":[{"title":"Robotics: Robot Outputs","spark_text":"This week, Grade 6 connects its vocabulary to robot outputs and signals.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Robot Outputs that your team should test carefully?"}],"after":{"title":"Instructions become movement","spark_text":"A wheeled robot uses motors to turn its wheels. Its program tells both motors to move forward for two seconds and then stop. A motor is an output device because it produces an action. Changing the instruction can change how the robot moves.","why_it_matters":"Movement depends on both the program and the robot's outputs.","question":"What is the output in this example, and which instruction controls how long it moves?"}},{"id":"technology_2026_g8_iit_june_week4_safe_debugging","before":[{"title":"Safe Debugging","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Safe Debugging that could help your Technology work this week?"}],"after":{"title":"Find the cause of the wrong result","spark_text":"A game should add one point for each star, but it adds two. Eva checks the scoring instructions and finds two 'add 1' commands running for the same star. She removes one and tests again. Debugging means finding and fixing the cause of a problem.","why_it_matters":"A useful fix addresses the cause and is checked with another test.","question":"What caused the extra point, and how can Eva check that her fix worked?"}},{"id":"technology_2026_g7_iit_july_week4_variables","before":[{"title":"Variables","spark_text":"This week, Grade 7 connects its vocabulary to variables and if/else choices.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Variables that could help your Technology work this week?"}],"after":{"title":"Remember the score","spark_text":"A game starts with a score of 0. Each time the player collects a star, the program adds 1 to score. A variable is a named value that a program can change. After three stars, score holds 3, so the game can display the current result.","why_it_matters":"A variable lets a program remember information while it runs.","question":"What value should score hold after five stars, and why does the game need to remember it?"}},{"id":"technology_2026_g9_iit_july_week4_python_and_data_data_science","before":[{"title":"Python and Data: Data Science","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Data Science that could help your work this week?"}],"after":{"title":"A pattern is not a prediction","spark_text":"A class records how many students cycle to school: Monday 4, Tuesday 6 and Wednesday 8. The count increases by two each day in these records. That is a pattern in the data. It does not prove that Thursday's count will be 10, because Thursday has not been measured.","why_it_matters":"A pattern describes the available evidence; a prediction still needs checking.","question":"What is the observed pattern, and why is Thursday's count still uncertain?"}},{"id":"technology_2026_g6_iit_july_week5_robotics_route_accuracy","before":[{"title":"Robotics: Route Accuracy","spark_text":"This week, Grade 6 connects its vocabulary to route maps and accurate movement.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Route Accuracy that your team should test carefully?"}],"after":{"title":"Make the turns more accurate","spark_text":"A robot is programmed to turn 90 degrees, but repeated tests show turns of about 100 degrees. The team adjusts its turning setting and tests again from the same start position. Calibration means adjusting a system using measurements so its results are closer to the intended value.","why_it_matters":"Measurements give a better reason for an adjustment than guessing.","question":"What measurement shows that an adjustment is needed, and what should the team test afterward?"}},{"id":"technology_2026_g7_iit_july_week5_operators","before":[{"title":"Operators","spark_text":"This week, Grade 7 connects its vocabulary to comparison and logic operators.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Operators that could help your Technology work this week?"}],"after":{"title":"Choose the right comparison","spark_text":"A program lets a player enter when age is at least 12. It checks age >= 12. The symbol >= means greater than or equal to. For age 12 the comparison is true; for age 11 it is false. A comparison produces a true-or-false result.","why_it_matters":"A small change in a comparison can change who meets a rule.","question":"Would age 13 pass this check? Explain what >= means."}},{"id":"technology_2026_g8_iit_july_week5_analog_values","before":[{"title":"Analog Values","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Analog Values that could help your Technology work this week?"}],"after":{"title":"More than on or off","spark_text":"A light sensor reports values from 0 to 100 in this example. It gives 20 in a dark place and 80 in a bright place. These values describe different amounts of light. A two-state signal would only distinguish two states, such as dark and bright.","why_it_matters":"A range of values can describe changes that an on/off signal cannot.","question":"What extra information does the value 80 provide compared with a simple on/off signal?"}},{"id":"technology_2026_g9_iit_july_week5_python_and_data_collection_plan","before":[{"title":"Python and Data: Collection Plan","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Collection Plan that could help your work this week?"}],"after":{"title":"Ask one clear survey question","spark_text":"A class wants to find its most popular club. It asks every student, 'Which one club would you choose: chess, art or music?' Everyone receives the same options and chooses once. Using a consistent question and one response per student makes the results easier to compare.","why_it_matters":"How data is collected affects what you can conclude from it.","question":"Why would allowing some students to vote twice make the comparison unfair?"}},{"id":"technology_2026_g6_iit_july_week6_repeat_patterns","before":[{"title":"Repeat Patterns","spark_text":"This week, Grade 6 connects its vocabulary to loops and repeated movement patterns.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Repeat Patterns that could help your Technology work this week?"}],"after":{"title":"A pattern is not a prediction","spark_text":"A class records how many students cycle to school: Monday 4, Tuesday 6 and Wednesday 8. The count increases by two each day in these records. That is a pattern in the data. It does not prove that Thursday's count will be 10, because Thursday has not been measured.","why_it_matters":"A pattern describes the available evidence; a prediction still needs checking.","question":"What is the observed pattern, and why is Thursday's count still uncertain?"}},{"id":"technology_2026_g7_iit_july_week6_loops","before":[{"title":"Loops","spark_text":"This week, Grade 7 connects its vocabulary to loops and timing.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Loops that could help your Technology work this week?"}],"after":{"title":"Repeat the instruction","spark_text":"A robot must move forward one step four times. A loop repeats instructions. Instead of writing 'move one step' four separate times, the programmer puts it inside a loop that repeats four times. Each repetition performs the same instruction once.","why_it_matters":"Loops reduce repeated instructions and make repeated actions easier to change.","question":"How many steps would the robot move if the loop repeated six times? Explain."}},{"id":"technology_2026_g8_iit_july_week6_light_and_rgb","before":[{"title":"Light and RGB","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Light and RGB that could help your Technology work this week?"}],"after":{"title":"Mix three light channels","spark_text":"An RGB light combines red, green and blue light. In this example, each channel can be set from 0 to 255. The setting red 255, green 0, blue 0 uses only red. Changing the three channel values changes the combined light.","why_it_matters":"Separate channel values let a program control the colour of a light.","question":"Which channel is active in the setting 255, 0, 0, and which two are off?"}},{"id":"technology_2026_g9_iit_july_week6_python_and_data_cleaning_and_model","before":[{"title":"Python and Data: Cleaning and Model","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Cleaning and Model that could help your work this week?"}],"after":{"title":"One club, two spellings","spark_text":"A survey lists the same club as 'Chess', 'chess' and 'Chess '. A computer may treat these as different text values when grouping records. Data cleaning means finding and fixing problems such as inconsistent labels. Ali checks that they refer to the same club before giving all three the same spelling.","why_it_matters":"Consistent labels help records that belong together stay together.","question":"Why should Ali check the labels before combining the three entries?"}},{"id":"technology_2026_g6_iit_july_week7_robotics_sensor_detection","before":[{"title":"Robotics: Sensor Detection","spark_text":"This week, Grade 6 connects its vocabulary to sensors, inputs, and responses.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Sensor Detection that your team should test carefully?"}],"after":{"title":"A reading triggers a response","spark_text":"A robot uses a distance sensor to measure how far away an object is. Its rule says: if the distance is less than 10 cm, stop the motors. A reading of 6 cm meets that condition; a reading of 15 cm does not.","why_it_matters":"A sensor reading can become the input to a programmed decision.","question":"Should the robot stop at 8 cm? Explain using the rule."}},{"id":"technology_2026_g7_iit_july_week7_debugging_roles","before":[{"title":"Debugging Roles","spark_text":"This week, Grade 7 connects its vocabulary to debugging and pair-programming roles.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Debugging Roles that could help your Technology work this week?"}],"after":{"title":"Make the next step clear","spark_text":"Two students edit the same shared poster. Both replace the title at the same time and lose track of the intended wording. They agree that one will edit the title while the other checks the image, then review the changes together. Collaboration needs clear responsibilities as well as shared access.","why_it_matters":"An agreed plan can prevent people from undoing each other's work.","question":"How does dividing these two tasks help the students work together?"}},{"id":"technology_2026_g8_iit_july_week7_buzzer_and_servo","before":[{"title":"Buzzer and Servo","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Buzzer and Servo that could help your Technology work this week?"}],"after":{"title":"Turn to a position","spark_text":"A small model gate uses a servo. The program tells it to move to 0 degrees to close the gate and 90 degrees to open it. A servo can be controlled to move to a position within its operating range. This differs from simply telling a wheel motor to keep turning.","why_it_matters":"Choosing the right output depends on the movement the model needs.","question":"Which position opens this model gate, and why is position control useful here?"}},{"id":"technology_2026_g9_iit_july_week7_python_and_data_charts_and_patterns","before":[{"title":"Python and Data: Charts and Patterns","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Charts and Patterns that could help your work this week?"}],"after":{"title":"Read the bars","spark_text":"A club survey counts 12 students in chess, 8 in art and 5 in music. A bar chart shows one bar for each club, using the same scale for every bar. The chess bar is tallest because 12 is the largest count. Labels tell the reader which club each bar represents.","why_it_matters":"A labelled chart makes comparisons easier to see.","question":"How many more students chose chess than music, and how would the bars show that difference?"}},{"id":"technology_2026_g6_iit_july_week8_conditions_and_flowcharts","before":[{"title":"Conditions and Flowcharts","spark_text":"This week, Grade 6 connects its vocabulary to simple conditions and robot responses.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Conditions and Flowcharts that could help your work this week?"}],"after":{"title":"Read the bars","spark_text":"A club survey counts 12 students in chess, 8 in art and 5 in music. A bar chart shows one bar for each club, using the same scale for every bar. The chess bar is tallest because 12 is the largest count. Labels tell the reader which club each bar represents.","why_it_matters":"A labelled chart makes comparisons easier to see.","question":"How many more students chose chess than music, and how would the bars show that difference?"}},{"id":"technology_2026_g7_iit_august_week8_dance_prep","before":[{"title":"Dance Prep","spark_text":"This week, Grade 7 connects its vocabulary to dance game preparation.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Dance Prep that could help your Technology work this week?"}],"after":{"title":"Instructions become movement","spark_text":"A wheeled robot uses motors to turn its wheels. Its program tells both motors to move forward for two seconds and then stop. A motor is an output device because it produces an action. Changing the instruction can change how the robot moves.","why_it_matters":"Movement depends on both the program and the robot's outputs.","question":"What is the output in this example, and which instruction controls how long it moves?"}},{"id":"technology_2026_g8_iit_july_week8_integrated_challenge","before":[{"title":"Integrated Challenge","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Integrated Challenge that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g9_iit_august_week8_python_and_data_data_product","before":[{"title":"Python and Data: Data Product","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Data Product that could help your work this week?"}],"after":{"title":"Remember the score","spark_text":"A game starts with a score of 0. Each time the player collects a star, the program adds 1 to score. A variable is a named value that a program can change. After three stars, score holds 3, so the game can display the current result.","why_it_matters":"A variable lets a program remember information while it runs.","question":"What value should score hold after five stars, and why does the game need to remember it?"}},{"id":"technology_2026_g6_iit_august_week9_knowledge_cards","before":[{"title":"Knowledge Cards","spark_text":"This week, Grade 6 connects its vocabulary to mBot card stations and actions.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Knowledge Cards that could help your Technology work this week?"}],"after":{"title":"Make a visible signal","spark_text":"A small board has an LED that a program can turn on and off. An LED is a light-emitting diode. A program turns it on for one second, then off for one second, and repeats. The changing light is an output that a person can see.","why_it_matters":"A light can communicate that a device is running or has changed state.","question":"What visible pattern does this program produce?"}},{"id":"technology_2026_g6_iit_july_week9_mini_challenge_plan","before":[{"title":"Mini-Challenge Plan","spark_text":"This week, Grade 6 connects its vocabulary to planning a small mBot challenge.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Mini-Challenge Plan that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g7_iit_august_week9_project_planning","before":[{"title":"Project Planning","spark_text":"This week, Grade 7 connects its vocabulary to dance game planning and scoring.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Project Planning that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g8_iit_august_week9_ultrasonic_design","before":[{"title":"Ultrasonic Design","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Ultrasonic Design that could help your Technology work this week?"}],"after":{"title":"A reading triggers a response","spark_text":"A robot uses a distance sensor to measure how far away an object is. Its rule says: if the distance is less than 10 cm, stop the motors. A reading of 6 cm meets that condition; a reading of 15 cm does not.","why_it_matters":"A sensor reading can become the input to a programmed decision.","question":"Should the robot stop at 8 cm? Explain using the rule."}},{"id":"technology_2026_g9_iit_august_week9_python_and_data_project_readiness","before":[{"title":"Python and Data: Project Readiness","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Project Readiness that could help your work this week?"}],"after":{"title":"Remember the score","spark_text":"A game starts with a score of 0. Each time the player collects a star, the program adds 1 to score. A variable is a named value that a program can change. After three stars, score holds 3, so the game can display the current result.","why_it_matters":"A variable lets a program remember information while it runs.","question":"What value should score hold after five stars, and why does the game need to remember it?"}},{"id":"technology_2026_g6_iit_august_week10_final_challenge_plan","before":[{"title":"Final Challenge Plan","spark_text":"This week, Grade 6 connects its vocabulary to planning and improving the final mBot challenge.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Final Challenge Plan that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g7_iit_august_week10_build","before":[{"title":"Build","spark_text":"This week, Grade 7 connects its vocabulary to building and testing dance game logic.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Build that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g8_iit_august_week10_prototype_build","before":[{"title":"Prototype Build","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Prototype Build that could help your Technology work this week?"}],"after":{"title":"Test the idea before building everything","spark_text":"A team sketches an app with a Home button and a Help button on paper. It asks a classmate where they would tap to find instructions. A prototype is an early version used to test an idea. The sketch lets the team check the navigation before programming it.","why_it_matters":"An early test can reveal a confusing design while it is still easy to change.","question":"What can the team learn from this paper prototype before it writes code?"}},{"id":"technology_2026_g9_iit_august_week10_python_and_data_visualization","before":[{"title":"Python and Data: Visualization","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Visualization that could help your work this week?"}],"after":{"title":"Read the bars","spark_text":"A club survey counts 12 students in chess, 8 in art and 5 in music. A bar chart shows one bar for each club, using the same scale for every bar. The chess bar is tallest because 12 is the largest count. Labels tell the reader which club each bar represents.","why_it_matters":"A labelled chart makes comparisons easier to see.","question":"How many more students chose chess than music, and how would the bars show that difference?"}},{"id":"technology_2026_g6_iit_august_week11_demo_reflection","before":[{"title":"Demo Reflection","spark_text":"This week, Grade 6 connects its vocabulary to testing, explaining, and reflecting on the final robotics challenge.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Demo Reflection that could help your Technology work this week?"}],"after":{"title":"Explain what changed","spark_text":"A student compares two versions of a poster. In the first, small text was hard to read. In the second, the text is larger, and three classmates can read it from the same distance. A reflection explains a change, its reason and the evidence of its effect.","why_it_matters":"Specific evidence makes a reflection more useful than simply saying 'It is better.'","question":"Which change did the student make, and what evidence suggests it helped?"}},{"id":"technology_2026_g7_iit_august_week11_improve","before":[{"title":"Improve","spark_text":"This week, Grade 7 connects its vocabulary to improving game features.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Improve that could help your Technology work this week?"}],"after":{"title":"Explain what changed","spark_text":"A student compares two versions of a poster. In the first, small text was hard to read. In the second, the text is larger, and three classmates can read it from the same distance. A reflection explains a change, its reason and the evidence of its effect.","why_it_matters":"Specific evidence makes a reflection more useful than simply saying 'It is better.'","question":"Which change did the student make, and what evidence suggests it helped?"}},{"id":"technology_2026_g8_iit_august_week11_reliability","before":[{"title":"Reliability","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Reliability that could help your Technology work this week?"}],"after":{"title":"One successful run is not enough","spark_text":"A robot reaches the finish once. On the next two runs, it stops early. A reliable system works consistently under the same conditions. The team keeps the route and starting point the same and repeats the test after making a change.","why_it_matters":"Repeated tests help show whether a result is consistent.","question":"Why does one successful run not prove that this robot is reliable?"}},{"id":"technology_2026_g9_iit_august_week11_python_and_data_revision","before":[{"title":"Python and Data: Revision","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Revision that could help your work this week?"}],"after":{"title":"Remember the score","spark_text":"A game starts with a score of 0. Each time the player collects a star, the program adds 1 to score. A variable is a named value that a program can change. After three stars, score holds 3, so the game can display the current result.","why_it_matters":"A variable lets a program remember information while it runs.","question":"What value should score hold after five stars, and why does the game need to remember it?"}},{"id":"technology_2026_g7_iit_august_week12_demo","before":[{"title":"Demo","spark_text":"This week, Grade 7 connects its vocabulary to demonstrating and reflecting on the dance game.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Demo that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g8_iit_august_week12_demonstration","before":[{"title":"Demonstration","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Demonstration that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g9_iit_august_week12_python_and_data_presentation","before":[{"title":"Python and Data: Presentation","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 second-trimester Python and data work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Python and Data: Presentation that could help your work this week?"}],"after":{"title":"Remember the score","spark_text":"A game starts with a score of 0. Each time the player collects a star, the program adds 1 to score. A variable is a named value that a program can change. After three stars, score holds 3, so the game can display the current result.","why_it_matters":"A variable lets a program remember information while it runs.","question":"What value should score hold after five stars, and why does the game need to remember it?"}},{"id":"technology_2026_g8_iit_august_week13_cleanup","before":[{"title":"Cleanup","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 second-trimester Arduino work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Cleanup that could help your Technology work this week?"}],"after":{"title":"Leave the workspace ready","spark_text":"At the end of a robotics lesson, a pair stops the robot, follows the teacher's power-down instructions, returns the parts to labelled spaces and saves its program. A routine is a repeated sequence of actions. Following the same agreed steps makes missing files or parts easier to notice.","why_it_matters":"A clear routine helps the next person find a usable workspace.","question":"Which action protects the students' code, and which action helps keep the parts organised?"}},{"id":"technology_2026_g6_iiit_september_week1_iiit_vocabulary","before":[{"title":"IIIT Vocabulary","spark_text":"This week, Grade 6 connects its vocabulary to core third-trimester words for the Grade 6 IIIT summative vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from IIIT Vocabulary that could help your Technology work this week?"}],"after":{"title":"Parts work together","spark_text":"A student types a sentence on a keyboard. The computer processes the input and shows the sentence on a screen. The keyboard provides input, the processor follows instructions, and the screen provides output. These connected parts work together as a computing system.","why_it_matters":"A system's result depends on parts performing connected jobs.","question":"What jobs do the keyboard and screen perform in this system?"}},{"id":"technology_2026_g7_iiit_september_week1_spreadsheets","before":[{"title":"Spreadsheets","spark_text":"This week, Grade 7 connects its vocabulary to core third-trimester words for the Grade 7 spreadsheet vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Spreadsheets that could help your Technology work this week?"}],"after":{"title":"Turn club choices into a table","spark_text":"A survey records three choices: Ana chose chess, Luis chose art, and Mei chose chess. A table can organise this data with two columns, Student and Club, and one row for each student. Keeping each student's name beside the correct club preserves the meaning of the records.","why_it_matters":"A clear table keeps related information together.","question":"What should appear in the two cells of Luis's row?"}},{"id":"technology_2026_g8_iiit_september_week1_app_design","before":[{"title":"App Design","spark_text":"This week, Grade 8 connects its vocabulary to core third-trimester words for the Grade 8 app design vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from App Design that could help your Technology work this week?"}],"after":{"title":"Test the idea before building everything","spark_text":"A team sketches an app with a Home button and a Help button on paper. It asks a classmate where they would tap to find instructions. A prototype is an early version used to test an idea. The sketch lets the team check the navigation before programming it.","why_it_matters":"An early test can reveal a confusing design while it is still easy to change.","question":"What can the team learn from this paper prototype before it writes code?"}},{"id":"technology_2026_g9_iiit_september_week1_digital_media","before":[{"title":"Digital Media","spark_text":"This week, Grade 9 connects its vocabulary to core third-trimester words for the Grade 9 digital media vocabulary table.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Digital Media that could help your Technology work this week?"}],"after":{"title":"Use media to support the message","spark_text":"An online guide explains how to pack a school bag. It includes a short paragraph and a photo showing the arranged items. The photo supports the explanation. An unrelated animated image would use attention without showing the reader how to complete the task.","why_it_matters":"Useful media helps the audience understand the intended message.","question":"Why does the packing photo help this guide more than an unrelated animation?"}},{"id":"technology_2026_g6_iiit_september_week2_formulas","before":[{"title":"Formulas","spark_text":"This week, Grade 6 connects its vocabulary to spreadsheet formulas and values.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Formulas that could help your Technology work this week?"}],"after":{"title":"Let the spreadsheet calculate","spark_text":"A spreadsheet stores 6 in cell B2 and 4 in cell B3. The formula =B2+B3 adds those values and shows 10. A formula is an instruction that calculates a result. If B3 changes to 7, the same formula shows 13 without being rewritten.","why_it_matters":"Cell references help calculations follow changes in the data.","question":"What would =B2+B3 show if B2 became 9 and B3 stayed 4? Explain."}},{"id":"technology_2026_g7_iiit_september_week2_formulas_and_charts","before":[{"title":"Formulas and Charts","spark_text":"This week, Grade 7 connects its vocabulary to formulas, functions, and chart interpretation.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Formulas and Charts that could help your work this week?"}],"after":{"title":"Let the spreadsheet calculate","spark_text":"A spreadsheet stores 6 in cell B2 and 4 in cell B3. The formula =B2+B3 adds those values and shows 10. A formula is an instruction that calculates a result. If B3 changes to 7, the same formula shows 13 without being rewritten.","why_it_matters":"Cell references help calculations follow changes in the data.","question":"What would =B2+B3 show if B2 became 9 and B3 stayed 4? Explain."}},{"id":"technology_2026_g8_iiit_september_week2_events_and_flow","before":[{"title":"Events and Flow","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Events and Flow that could help your Technology work this week?"}],"after":{"title":"What starts the action?","spark_text":"An app has a button labelled Play. Pressing that button is an event. The app responds by playing a sound. The button itself is not the sound; it is the control that triggers the action. Without the event, this sound does not start.","why_it_matters":"An event connects something the user does with a response from the program.","question":"What is the event in this example, and what action does it trigger?"}},{"id":"technology_2026_g9_iiit_september_week2_sound_quality","before":[{"title":"Sound Quality","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Sound Quality that could help your Technology work this week?"}],"after":{"title":"Make the message clear","spark_text":"A recording contains a quiet voice and loud background music. Listeners struggle to understand the words. The editor lowers the music and tests the recording again. Sound quality includes how clearly the intended sound can be heard, not just how loud the whole recording is.","why_it_matters":"Listeners need to hear the message clearly.","question":"Why could lowering the music improve this recording more than making everything louder?"}},{"id":"technology_2026_g8_iiit_september_week3_user_needs","before":[{"title":"User Needs","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from User Needs that could help your Technology work this week?"}],"after":{"title":"Design for the person using it","spark_text":"A club makes a lunch-order app for younger students. In a trial, several users cannot find the order button because its label says 'Execute'. The team changes it to 'Place order' and tests again. A user need is something the intended person must be able to understand or do.","why_it_matters":"A design should help its intended users complete their task.","question":"Which user need does the new button label address?"}},{"id":"technology_2026_g6_iiit_october_week1_budget_planning","before":[{"title":"Budget Planning","spark_text":"This week, Grade 6 connects its vocabulary to planning with quantities, costs, and totals.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Budget Planning that could help your Technology work this week?"}],"after":{"title":"Can the budget cover it?","spark_text":"A class has $20 for materials. Card costs $8, tape costs $5 and markers cost $4. A budget compares the money available with planned costs. These items cost $17 altogether, leaving $3. Adding another $5 item would make the total greater than $20.","why_it_matters":"Checking costs before buying helps a group stay within its limit.","question":"Can the class add the $5 item without changing its plan? Explain using the totals."}},{"id":"technology_2026_g7_iiit_october_week3_data_analysis","before":[{"title":"Data Analysis","spark_text":"This week, Grade 7 connects its vocabulary to sorting, filtering, and patterns.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Data Analysis that could help your work this week?"}],"after":{"title":"Numbers need labels","spark_text":"A file contains the values 12, 8 and 5. Without labels, Jo cannot tell what they describe. She adds the labels Chess, Art and Music and the heading Number of students. Data is recorded information. Labels give these numbers the context needed to interpret them.","why_it_matters":"A number alone may not tell a reader what was measured.","question":"What information was missing before Jo added the labels?"}},{"id":"technology_2026_g9_iiit_october_week3_personal_data","before":[{"title":"Personal Data","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Personal Data that could help your work this week?"}],"after":{"title":"Which details should stay private?","spark_text":"A game profile asks Ana to choose a display name. Another player asks for her home address and password. A display name can identify her in the game without revealing her address. She does not need to share her address or password to play with someone.","why_it_matters":"Sharing fewer personal details gives strangers less information about you.","question":"Which two details should Ana keep private, and why?"}},{"id":"technology_2026_g7_iiit_october_week4_scratch_decomposition","before":[{"title":"Scratch Decomposition","spark_text":"This week, Grade 7 connects its vocabulary to decomposition and subroutines.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Scratch Decomposition that could help your Technology work this week?"}],"after":{"title":"Break the game into parts","spark_text":"A group wants to make a collecting game. It separates the work into moving the player, placing objects and updating the score. Decomposition means breaking a large problem into smaller parts. The group can build and test each part before combining them.","why_it_matters":"Smaller tasks are easier to explain, share and test.","question":"Name two smaller tasks from the reading and explain why testing them separately could help."}},{"id":"technology_2026_g8_iiit_october_week4_first_python","before":[{"title":"First Python","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from First Python that could help your work this week?"}],"after":{"title":"Remember the score","spark_text":"A game starts with a score of 0. Each time the player collects a star, the program adds 1 to score. A variable is a named value that a program can change. After three stars, score holds 3, so the game can display the current result.","why_it_matters":"A variable lets a program remember information while it runs.","question":"What value should score hold after five stars, and why does the game need to remember it?"}},{"id":"technology_2026_g9_iiit_october_week4_social_engineering_and_malware","before":[{"title":"Social Engineering and Malware","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Social Engineering and Malware that could help your Technology work this week?"}],"after":{"title":"Pause before you send","spark_text":"Leo receives a message that says, 'Send your password now or your account will close.' The message tries to make him act quickly. A password is private information. Instead of replying or using the message's link, Leo can open the service through its usual app and ask a trusted adult for help.","why_it_matters":"An urgent message can pressure someone into sharing private information.","question":"What should Leo do instead of sending his password? Explain why."}},{"id":"technology_2026_g6_iiit_october_week2_charts","before":[{"title":"Charts","spark_text":"This week, Grade 6 connects its vocabulary to chart parts and conclusions.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Charts that could help your work this week?"}],"after":{"title":"Read the bars","spark_text":"A club survey counts 12 students in chess, 8 in art and 5 in music. A bar chart shows one bar for each club, using the same scale for every bar. The chess bar is tallest because 12 is the largest count. Labels tell the reader which club each bar represents.","why_it_matters":"A labelled chart makes comparisons easier to see.","question":"How many more students chose chess than music, and how would the bars show that difference?"}},{"id":"technology_2026_g7_iiit_october_week5_sources_and_lists","before":[{"title":"Sources and Lists","spark_text":"This week, Grade 7 connects its vocabulary to lists, credible sources, and citation.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one data detail, pattern, or Python idea from Sources and Lists that could help your work this week?"}],"after":{"title":"A claim needs evidence","spark_text":"A post claims that the school will close tomorrow, but it gives no source. Omar checks the school's official notice and finds that classes will continue. A source is where information comes from. Comparing the post with an official notice helps him decide whether to share it.","why_it_matters":"Checking the original source can stop an unsupported claim from spreading.","question":"Which source should Omar rely on here, and what evidence supports his choice?"}},{"id":"technology_2026_g8_iiit_october_week5_numbers_and_selection","before":[{"title":"Numbers and Selection","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Numbers and Selection that could help your Technology work this week?"}],"after":{"title":"Choose the right comparison","spark_text":"A program lets a player enter when age is at least 12. It checks age >= 12. The symbol >= means greater than or equal to. For age 12 the comparison is true; for age 11 it is false. A comparison produces a true-or-false result.","why_it_matters":"A small change in a comparison can change who meets a rule.","question":"Would age 13 pass this check? Explain what >= means."}},{"id":"technology_2026_g9_iiit_october_week5_security_risk","before":[{"title":"Security Risk","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Security Risk that could help your Technology work this week?"}],"after":{"title":"Spot the risk before it happens","spark_text":"A group plans to keep its only project file on a shared computer. Other people use that computer and may delete the file. A risk is the possibility that something unwanted could happen. Saving a separate backup reduces the harm if the working file is lost.","why_it_matters":"Naming a risk helps you choose a useful protection.","question":"What is the risk in this situation, and which action would reduce its impact?"}},{"id":"technology_2026_g6_iiit_october_week3_3d_basics","before":[{"title":"3D Basics","spark_text":"This week, Grade 6 connects its vocabulary to basic 3D modeling actions.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from 3D Basics that could help your Technology work this week?"}],"after":{"title":"A model has three dimensions","spark_text":"A digital box model is 4 cm wide, 3 cm deep and 2 cm high. A 3D model represents width, depth and height. If the designer doubles only the height, the new model is 4 cm wide, 3 cm deep and 4 cm high.","why_it_matters":"Checking each dimension helps a designer change the intended part of a model.","question":"Which dimension changes in this example, and which two stay the same?"}},{"id":"technology_2026_g7_iiit_october_week6_blog_media","before":[{"title":"Blog Media","spark_text":"This week, Grade 7 connects its vocabulary to blog posts and media layout.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Blog Media that could help your Technology work this week?"}],"after":{"title":"Use media to support the message","spark_text":"An online guide explains how to pack a school bag. It includes a short paragraph and a photo showing the arranged items. The photo supports the explanation. An unrelated animated image would use attention without showing the reader how to complete the task.","why_it_matters":"Useful media helps the audience understand the intended message.","question":"Why does the packing photo help this guide more than an unrelated animation?"}},{"id":"technology_2026_g8_iiit_october_week6_loops_and_branches","before":[{"title":"Loops and Branches","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Loops and Branches that could help your Technology work this week?"}],"after":{"title":"Choose an action with a condition","spark_text":"A game checks whether the player has at least 10 points. If the condition is true, it opens the next level. If the condition is false, the player stays in the current level. A condition is a statement a program can check as true or false.","why_it_matters":"Conditions let a program choose between actions.","question":"What happens at 8 points and at 10 points? Use the rule in the reading."}},{"id":"technology_2026_g9_iiit_october_week6_project_problem","before":[{"title":"Project Problem","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Project Problem that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g6_iiit_october_week4_design_prototype","before":[{"title":"Design Prototype","spark_text":"This week, Grade 6 connects its vocabulary to planning and improving a simple model.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Design Prototype that could help your Technology work this week?"}],"after":{"title":"Test the idea before building everything","spark_text":"A team sketches an app with a Home button and a Help button on paper. It asks a classmate where they would tap to find instructions. A prototype is an early version used to test an idea. The sketch lets the team check the navigation before programming it.","why_it_matters":"An early test can reveal a confusing design while it is still easy to change.","question":"What can the team learn from this paper prototype before it writes code?"}},{"id":"technology_2026_g7_iiit_october_week7_robotics_sensor_systems","before":[{"title":"Robotics: Sensor Systems","spark_text":"This week, Grade 7 connects its vocabulary to micro:bit input and output systems.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Sensor Systems that your team should test carefully?"}],"after":{"title":"A reading triggers a response","spark_text":"A robot uses a distance sensor to measure how far away an object is. Its rule says: if the distance is less than 10 cm, stop the motors. A reading of 6 cm meets that condition; a reading of 15 cm does not.","why_it_matters":"A sensor reading can become the input to a programmed decision.","question":"Should the robot stop at 8 cm? Explain using the rule."}},{"id":"technology_2026_g8_iiit_october_week7_debugging","before":[{"title":"Debugging","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Debugging that could help your Technology work this week?"}],"after":{"title":"Find the cause of the wrong result","spark_text":"A game should add one point for each star, but it adds two. Eva checks the scoring instructions and finds two 'add 1' commands running for the same star. She removes one and tests again. Debugging means finding and fixing the cause of a problem.","why_it_matters":"A useful fix addresses the cause and is checked with another test.","question":"What caused the extra point, and how can Eva check that her fix worked?"}},{"id":"technology_2026_g9_iiit_october_week7_risk_map","before":[{"title":"Risk Map","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Risk Map that could help your Technology work this week?"}],"after":{"title":"Spot the risk before it happens","spark_text":"A group plans to keep its only project file on a shared computer. Other people use that computer and may delete the file. A risk is the possibility that something unwanted could happen. Saving a separate backup reduces the harm if the working file is lost.","why_it_matters":"Naming a risk helps you choose a useful protection.","question":"What is the risk in this situation, and which action would reduce its impact?"}},{"id":"technology_2026_g6_iiit_november_week1_present_and_reflect","before":[{"title":"Present and Reflect","spark_text":"This week, Grade 6 connects its vocabulary to presenting, feedback, and reflection.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Present and Reflect that could help your Technology work this week?"}],"after":{"title":"Explain what changed","spark_text":"A student compares two versions of a poster. In the first, small text was hard to read. In the second, the text is larger, and three classmates can read it from the same distance. A reflection explains a change, its reason and the evidence of its effect.","why_it_matters":"Specific evidence makes a reflection more useful than simply saying 'It is better.'","question":"Which change did the student make, and what evidence suggests it helped?"}},{"id":"technology_2026_g7_iiit_november_week8_test_table","before":[{"title":"Test Table","spark_text":"This week, Grade 7 connects its vocabulary to sensor testing and reliability.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Test Table that could help your Technology work this week?"}],"after":{"title":"Turn club choices into a table","spark_text":"A survey records three choices: Ana chose chess, Luis chose art, and Mei chose chess. A table can organise this data with two columns, Student and Club, and one row for each student. Keeping each student's name beside the correct club preserves the meaning of the records.","why_it_matters":"A clear table keeps related information together.","question":"What should appear in the two cells of Luis's row?"}},{"id":"technology_2026_g8_iiit_october_week8_micro_bit_setup","before":[{"title":"Micro:bit Setup","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Micro:bit Setup that could help your Technology work this week?"}],"after":{"title":"An input leads to an output","spark_text":"A small board has a button and a light display. Pressing the button gives the program an input. The program follows an instruction to show a heart on the display. The visible heart is an output. Input is information received; output is a result produced.","why_it_matters":"Following an input through to its output helps explain how a device works.","question":"What is the input in this example, and what output does it cause?"}},{"id":"technology_2026_g9_iiit_november_week8_proposal","before":[{"title":"Proposal","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Proposal that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g6_iiit_november_week2_micro_bit_input_and_output","before":[{"title":"micro:bit Input and Output","spark_text":"This week, Grade 6 connects its vocabulary to micro:bit parts, inputs, and outputs.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from micro:bit Input and Output that could help your Technology work this week?"}],"after":{"title":"An input leads to an output","spark_text":"A small board has a button and a light display. Pressing the button gives the program an input. The program follows an instruction to show a heart on the display. The visible heart is an output. Input is information received; output is a result produced.","why_it_matters":"Following an input through to its output helps explain how a device works.","question":"What is the input in this example, and what output does it cause?"}},{"id":"technology_2026_g7_iiit_november_week9_review_setup","before":[{"title":"Review Setup","spark_text":"This week, Grade 7 connects its vocabulary to reviewing third-trimester concepts.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Review Setup that could help your Technology work this week?"}],"after":{"title":"Write down what actually happened","spark_text":"A button is supposed to turn a light on. In a test table, Sam records Expected: light turns on; Actual: light stays off. A test compares what should happen with what does happen. Recording the difference gives a clear starting point for finding the problem.","why_it_matters":"An actual result is evidence, even when the test fails.","question":"Did this test pass? Explain using the expected and actual results."}},{"id":"technology_2026_g8_iiit_november_week9_binary_representation","before":[{"title":"Binary Representation","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Binary Representation that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g9_iiit_november_week9_project_habits","before":[{"title":"Project Habits","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Project Habits that could help your Technology work this week?"}],"after":{"title":"Two symbols can represent information","spark_text":"A display uses three lights. Each light is either off, written 0, or on, written 1. The patterns 001 and 010 use the same two symbols but put them in different positions. A binary representation uses two possible symbols or states to encode information.","why_it_matters":"Both the states and their positions can carry meaning.","question":"How are 001 and 010 different even though each has only one light on?"}},{"id":"technology_2026_g6_iiit_november_week3_micro_bit_variables","before":[{"title":"micro:bit Variables","spark_text":"This week, Grade 6 connects its vocabulary to counters and changing values.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from micro:bit Variables that could help your Technology work this week?"}],"after":{"title":"Remember the score","spark_text":"A game starts with a score of 0. Each time the player collects a star, the program adds 1 to score. A variable is a named value that a program can change. After three stars, score holds 3, so the game can display the current result.","why_it_matters":"A variable lets a program remember information while it runs.","question":"What value should score hold after five stars, and why does the game need to remember it?"}},{"id":"technology_2026_g7_iiit_november_week10_project_plan","before":[{"title":"Project Plan","spark_text":"This week, Grade 7 connects its vocabulary to planning the Mandrake Detection System.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Project Plan that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g8_iiit_november_week10_game_build","before":[{"title":"Game Build","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Game Build that could help your Technology work this week?"}],"after":{"title":"Break the game into parts","spark_text":"A group wants to make a collecting game. It separates the work into moving the player, placing objects and updating the score. Decomposition means breaking a large problem into smaller parts. The group can build and test each part before combining them.","why_it_matters":"Smaller tasks are easier to explain, share and test.","question":"Name two smaller tasks from the reading and explain why testing them separately could help."}},{"id":"technology_2026_g9_iiit_november_week10_build_evidence","before":[{"title":"Build Evidence","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Build Evidence that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g7_iiit_november_week11_debug_reliability","before":[{"title":"Debug Reliability","spark_text":"This week, Grade 7 connects its vocabulary to retesting and improving reliability.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Debug Reliability that could help your Technology work this week?"}],"after":{"title":"Find the cause of the wrong result","spark_text":"A game should add one point for each star, but it adds two. Eva checks the scoring instructions and finds two 'add 1' commands running for the same star. She removes one and tests again. Debugging means finding and fixing the cause of a problem.","why_it_matters":"A useful fix addresses the cause and is checked with another test.","question":"What caused the extra point, and how can Eva check that her fix worked?"}},{"id":"technology_2026_g8_iiit_november_week11_user_testing","before":[{"title":"User Testing","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from User Testing that could help your Technology work this week?"}],"after":{"title":"Design for the person using it","spark_text":"A club makes a lunch-order app for younger students. In a trial, several users cannot find the order button because its label says 'Execute'. The team changes it to 'Place order' and tests again. A user need is something the intended person must be able to understand or do.","why_it_matters":"A design should help its intended users complete their task.","question":"Which user need does the new button label address?"}},{"id":"technology_2026_g9_iiit_november_week11_testing_and_improvement","before":[{"title":"Testing and Improvement","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Testing and Improvement that could help your Technology work this week?"}],"after":{"title":"Explain what changed","spark_text":"A student compares two versions of a poster. In the first, small text was hard to read. In the second, the text is larger, and three classmates can read it from the same distance. A reflection explains a change, its reason and the evidence of its effect.","why_it_matters":"Specific evidence makes a reflection more useful than simply saying 'It is better.'","question":"Which change did the student make, and what evidence suggests it helped?"}},{"id":"technology_2026_g7_iiit_november_week12_presentation","before":[{"title":"Presentation","spark_text":"This week, Grade 7 connects its vocabulary to presenting the final system.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Presentation that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g8_iiit_november_week12_presentation","before":[{"title":"Presentation","spark_text":"This week, Grade 8 connects its vocabulary to Grade 8 third-trimester app, Python, and Micro:bit work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Presentation that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g6_iiit_december_week1_robotics_sensors_and_conditions","before":[{"title":"Robotics: Sensors and Conditions","spark_text":"This week, Grade 6 connects its vocabulary to sensors, conditions, and messages.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one robot behavior, sensor detail, or safety habit from Robotics: Sensors and Conditions that your team should test carefully?"}],"after":{"title":"Choose an action with a condition","spark_text":"A game checks whether the player has at least 10 points. If the condition is true, it opens the next level. If the condition is false, the player stays in the current level. A condition is a statement a program can check as true or false.","why_it_matters":"Conditions let a program choose between actions.","question":"What happens at 8 points and at 10 points? Use the rule in the reading."}},{"id":"technology_2026_g9_iiit_december_week12_final_demo","before":[{"title":"Final Demo","spark_text":"This week, Grade 9 connects its vocabulary to Grade 9 third-trimester STEM and cybersecurity work.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Final Demo that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"technology_2026_g6_iiit_december_week2_final_project","before":[{"title":"Final Project","spark_text":"This week, Grade 6 connects its vocabulary to building and improving the final micro:bit project.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Final Project that could help your Technology work this week?"}],"after":{"title":"A plan needs a clear first step","spark_text":"A group wants to create a guide for new students. It names the audience, lists the three questions the guide must answer, and assigns someone to draft each answer. A project plan describes the intended result and manageable steps toward it.","why_it_matters":"A specific plan makes it easier to begin and check progress.","question":"What should the group decide about its audience and content before making the guide?"}},{"id":"technology_2026_g6_iiit_december_week3_demonstrate_and_explain","before":[{"title":"Demonstrate and Explain","spark_text":"This week, Grade 6 connects its vocabulary to demonstrating and explaining the final project.","why_it_matters":"This connects the weekly vocabulary to the work students will practice in class.","question":"What is one idea from Demonstrate and Explain that could help your Technology work this week?"}],"after":{"title":"Show evidence of the result","spark_text":"A team presents its game. Instead of only saying 'It works', it shows a player collecting a star and the score changing from 0 to 1. A demonstration shows the system performing an action. Explaining the visible result helps the audience assess the team's claim.","why_it_matters":"A clear demonstration connects a claim with something the audience can observe.","question":"What evidence supports the team's claim that scoring works?"}},{"id":"grade6_t3_2026_w01_part1_spark","before":[{"title":"G6 T3 W01 Part 1 - Find a spreadsheet cell","spark_text":"Row 3 holds all the information about the chess club. Column B holds the number of students in each club.","why_it_matters":"Find a cell using its column letter and row number.","question":"B3 uses column B and row 3. Which part of C4 names the row?"}],"after":{"title":"Find the right spreadsheet cell · Part 1","spark_text":"A spreadsheet has columns labelled A, B and C, and rows numbered 1, 2 and 3. A column runs down the sheet; a row runs across it. A cell address combines the column letter and row number. B3 means column B, row 3.","why_it_matters":"Cell addresses let you point to an exact place in a spreadsheet.","question":"In C2, which part names the column and which part names the row?"}},{"id":"grade6_t3_2026_w01_part2_spark","before":[{"title":"G6 T3 W01 Part 2 - Turn sentences into a table","spark_text":"The data shows that 12 students chose chess. The table puts club names beside their student counts.","why_it_matters":"Put four story records into the correct spreadsheet cells.","question":"A club has 12 students. Where would its name and count go in a table?"}],"after":{"title":"Turn club choices into a table · Part 2","spark_text":"A survey records three choices: Ana chose chess, Luis chose art, and Mei chose chess. A table can organise this data with two columns, Student and Club, and one row for each student. Keeping each student's name beside the correct club preserves the meaning of the records.","why_it_matters":"A clear table keeps related information together.","question":"What should appear in the two cells of Luis's row?"}},{"id":"grade6_t3_2026_w02_part1_spark","before":[{"title":"G6 T3 W02 Part 1 - Build a column chart","spark_text":"The table puts club names beside their student counts. The chart uses bars to compare the club counts.","why_it_matters":"Make a labelled column chart from your club table.","question":"What is easier to compare in a bar chart than in a table?"},{"title":"G6 T3 W02 - Cells and charts - Words in use 1","spark_text":"Row 3 contains the club name and its student count. Column B contains the student counts. Cell B3 contains the number of students in the club.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"Find the right spreadsheet cell · Part 1","spark_text":"A spreadsheet has columns labelled A, B and C, and rows numbered 1, 2 and 3. A column runs down the sheet; a row runs across it. A cell address combines the column letter and row number. B3 means column B, row 3.","why_it_matters":"Cell addresses let you point to an exact place in a spreadsheet.","question":"In C2, which part names the column and which part names the row?"}},{"id":"grade6_t3_2026_w02_part2_spark","before":[{"title":"G6 T3 W02 Part 2 - Read spreadsheet cells","spark_text":"Row 3 holds all the information about the chess club. Column B holds the number of students in each club.","why_it_matters":"Find cell addresses and explain two values in a table.","question":"B3 uses column B and row 3. Which part of C4 names the row?"},{"title":"G6 T3 W02 - Cells and charts - Words in use 2","spark_text":"The table puts each club name beside its student count. The chart uses bars to compare the club counts.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"Find the right spreadsheet cell · Part 2","spark_text":"A spreadsheet has columns labelled A, B and C, and rows numbered 1, 2 and 3. A column runs down the sheet; a row runs across it. A cell address combines the column letter and row number. B3 means column B, row 3.","why_it_matters":"Cell addresses let you point to an exact place in a spreadsheet.","question":"In C2, which part names the column and which part names the row?"}},{"id":"grade6_t3_2026_w03_part1_spark","before":[{"title":"G6 T3 W03 Part 1 - Build a table and chart","spark_text":"The data shows that 12 students chose chess. The chart uses bars to compare the club counts.","why_it_matters":"Turn four story records into a table and labelled column chart.","question":"Which bar would be taller: a club with 12 students or one with 8?"},{"title":"G6 T3 W03 - Tables and story data - Words in use 1","spark_text":"The data shows that twelve students chose chess. The table puts each club name beside its student count. Row 3 contains the club name and its student count.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"Turn club choices into a table · Part 1","spark_text":"A survey records three choices: Ana chose chess, Luis chose art, and Mei chose chess. A table can organise this data with two columns, Student and Club, and one row for each student. Keeping each student's name beside the correct club preserves the meaning of the records.","why_it_matters":"A clear table keeps related information together.","question":"What should appear in the two cells of Luis's row?"}},{"id":"grade6_t3_2026_w03_part2_spark","before":[{"title":"G6 T3 W03 Part 2 - Build a story table","spark_text":"The table puts club names beside their student counts. The data shows that 12 students chose chess.","why_it_matters":"Create an accurate eight-record spreadsheet table.","question":"Why should a club name and its student count stay in the same row?"},{"title":"G6 T3 W03 - Tables and story data - Words in use 2","spark_text":"Column B contains the student counts. The chart uses bars to compare the club counts.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"Read the bars · Part 2","spark_text":"A club survey counts 12 students in chess, 8 in art and 5 in music. A bar chart shows one bar for each club, using the same scale for every bar. The chess bar is tallest because 12 is the largest count. Labels tell the reader which club each bar represents.","why_it_matters":"A labelled chart makes comparisons easier to see.","question":"How many more students chose chess than music, and how would the bars show that difference?"}},{"id":"grade6_t3_2026_w04_part1_spark","before":[{"title":"G6 T3 W04 Part 1 - Plan your STEAM work","spark_text":"The paper bridge is a prototype we can test before building a stronger bridge. The small cardboard model shows the shape of the bridge.","why_it_matters":"Choose one project task and state how you will check it.","question":"What could you test with a paper prototype before building a stronger version?"},{"title":"G6 T3 W04 - Finish and check spreadsheets - Words in use 1","spark_text":"The table puts each club name beside its student count. The chart uses bars to compare the club counts. The label under each bar names the club.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"Read the bars · Part 1","spark_text":"A club survey counts 12 students in chess, 8 in art and 5 in music. A bar chart shows one bar for each club, using the same scale for every bar. The chess bar is tallest because 12 is the largest count. Labels tell the reader which club each bar represents.","why_it_matters":"A labelled chart makes comparisons easier to see.","question":"How many more students chose chess than music, and how would the bars show that difference?"}},{"id":"grade6_t3_2026_w04_part2_spark","before":[{"title":"G6 T3 W04 Part 2 - Build your STEAM part","spark_text":"The paper bridge is a prototype we can test before building a stronger bridge. The small cardboard model shows the shape of the bridge.","why_it_matters":"Complete one contribution to your assigned group project.","question":"What could you test with a paper prototype before building a stronger version?"},{"title":"G6 T3 W04 - Finish and check spreadsheets - Words in use 2","spark_text":"The value in B3 is 12. Our comparison shows that chess has more students than art.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"Turn club choices into a table · Part 2","spark_text":"A survey records three choices: Ana chose chess, Luis chose art, and Mei chose chess. A table can organise this data with two columns, Student and Club, and one row for each student. Keeping each student's name beside the correct club preserves the meaning of the records.","why_it_matters":"A clear table keeps related information together.","question":"What should appear in the two cells of Luis's row?"}},{"id":"grade6_t3_2026_w07_part1_spark","before":[{"title":"G6 T3 W07 Part 1 - Make a table and chart","spark_text":"The table puts club names beside their student counts. The chart uses bars to compare the club counts.","why_it_matters":"Use four story records to make a table and labelled column chart.","question":"What is easier to compare in a bar chart than in a table?"},{"title":"G6 T3 W07 - Measure and model an eraser - Words in use 1","spark_text":"Check each dimension of the model against the eraser. The length of the eraser is 50 millimetres. The width of the eraser is 20 millimetres.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"A model has three dimensions · Part 1","spark_text":"A digital box model is 4 cm wide, 3 cm deep and 2 cm high. A 3D model represents width, depth and height. If the designer doubles only the height, the new model is 4 cm wide, 3 cm deep and 4 cm high.","why_it_matters":"Checking each dimension helps a designer change the intended part of a model.","question":"Which dimension changes in this example, and which two stay the same?"}},{"id":"grade6_t3_2026_w07_part2_spark","before":[{"title":"G6 T3 W07 Part 2 - Check your table and chart","spark_text":"The table puts club names beside their student counts. The chart uses bars to compare the club counts.","why_it_matters":"6B completes its chart assessment; 6A and 6C check their saved work.","question":"What is easier to compare in a bar chart than in a table?"},{"title":"G6 T3 W07 - Measure and model an eraser - Words in use 2","spark_text":"The height of the eraser is 10 millimetres. The digital model has the same dimensions as the eraser.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"A model has three dimensions · Part 2","spark_text":"A digital box model is 4 cm wide, 3 cm deep and 2 cm high. A 3D model represents width, depth and height. If the designer doubles only the height, the new model is 4 cm wide, 3 cm deep and 4 cm high.","why_it_matters":"Checking each dimension helps a designer change the intended part of a model.","question":"Which dimension changes in this example, and which two stay the same?"}},{"id":"grade6_t3_2026_w10_part1_spark","before":[{"title":"G6 T3 W10 Part 1 - Check a model; build a counter","spark_text":"6A and 6B enter each dimension as input in Tinkercad and check the model shown as output. 6C presses a button as input and checks the counter number as output.","why_it_matters":"6A and 6B check model sizes; 6C builds a button counter.","question":"Which part of your task is the input, and what output do you check?"},{"title":"G6 T3 W10 - Button counters - Words in use 1","spark_text":"Pressing button A provides an input to the program. The displayed number is an output from the counter. The variable count stores the number of button presses.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"A press changes the state · Part 1","spark_text":"A device starts with its light off. Each new button press changes the light to the opposite state: off becomes on, and on becomes off. This is a toggle. After two presses, the light is off again. The program must remember its current state between presses.","why_it_matters":"Remembering state lets the same input have the correct next effect.","question":"Starting with the light off, what state should it have after three presses? Explain."}},{"id":"grade6_t3_2026_w10_part2_spark","before":[{"title":"G6 T3 W10 Part 2 - Demonstrate your saved work","spark_text":"A test compares the saved result with the rule for the task. The feedback names one change that would improve that result.","why_it_matters":"Show your group’s saved work and explain one check.","question":"What result will you test, and what feedback would help you improve it?"},{"title":"G6 T3 W10 - Button counters - Words in use 2","spark_text":"Press the button to add one to the counter. The counter increases by one after each button press.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"A press changes the state · Part 2","spark_text":"A device starts with its light off. Each new button press changes the light to the opposite state: off becomes on, and on becomes off. This is a toggle. After two presses, the light is off again. The program must remember its current state between presses.","why_it_matters":"Remembering state lets the same input have the correct next effect.","question":"Starting with the light off, what state should it have after three presses? Explain."}},{"id":"grade6_t3_2026_w11_part1_spark","before":[{"title":"G6 T3 W11 Part 1 - Control a micro:bit response","spark_text":"Pressing button A gives the program an input. The number shown on the screen is an output.","why_it_matters":"6A and 6B build a counter; 6C predicts a light response.","question":"Name the input and output in the example you just read."},{"title":"G6 T3 W11 - Explain and improve saved work - Words in use 1","spark_text":"Pressing button A provides an input to the program. The displayed number is an output from the counter. The variable count stores the number of button presses.","why_it_matters":"Use these words to explain what happens in this week’s Technology work.","question":"Choose one example. Explain what its vocabulary word means in that situation."}],"after":{"title":"A press changes the state · Part 1","spark_text":"A device starts with its light off. Each new button press changes the light to the opposite state: off becomes on, and on becomes off. This is a toggle. After two presses, the light is off again. The program must remember its current state between presses.","why_it_matters":"Remembering state lets the same input have the correct next effect.","question":"Starting with the light off, what state should it have after three presses? Explain."}},{"id":"grade6_t3_2026_w11_part2_spark","before":[{"title":"G6 T3 W11 Part 2 - Test your micro:bit program","spark_text":"We test the program with a known input and check the response. The feedback names the response that needs to change.","why_it_matters":"6A and 6B test a counter; 6C builds and tests a night-light.","question":"What result will you test, and what feedback would help you improve it?"},{"title":"G6 T3 W11 - Explain and improve saved work - Words in use 2","spark_text":"We test the program by pressing the button three times. The feedback says to check the displayed total after a reset.","why_it_matters":"U