create temporary table standalone_spark_material_updates on commit drop as
select s.id,p.p->'after' as value from public.weekly_sparks s join standalone_spark_patch p on p.p->>'id'=s.id
where coalesce(jsonb_array_length(s.questions),0)=0 and coalesce(s.grade_questions,'{}'::jsonb)='{}'::jsonb
and (jsonb_build_object('title',s.title,'spark_text',s.spark_text,'why_it_matters',s.why_it_matters,'question',s.question) = p.p->'after'
 or exists(select 1 from jsonb_array_elements(p.p->'before') old where old=jsonb_build_object('title',s.title,'spark_text',s.spark_text,'why_it_matters',s.why_it_matters,'question',s.question)));
update public.weekly_sparks s set title=u.value->>'title',spark_text=u.value->>'spark_text',why_it_matters=u.value->>'why_it_matters',question=u.value->>'question'
from standalone_spark_material_updates u where u.id=s.id;
create temporary table standalone_spark_version_updates on commit drop as
select v.id,p.p->'after' as value from private.class_material_versions v join standalone_spark_patch p on p.p->>'id'=v.spark_id
where coalesce(jsonb_array_length(v.student_content->'questions'),0)=0
and coalesce(v.student_content->'gradeQuestions','{}'::jsonb)='{}'::jsonb
and not exists(select 1 from public.class_assignments a join public.class_assignment_responses r on r.assignment_id=a.id where a.version_id=v.id)
and (jsonb_build_object('title',v.student_content->>'title','spark_text',v.student_content->>'sparkText','why_it_matters',v.student_content->>'whyItMatters','question',v.student_content->>'question')=p.p->'after'
 or exists(select 1 from jsonb_array_elements(p.p->'before') old where old=jsonb_build_object('title',v.student_content->>'title','spark_text',v.student_content->>'sparkText','why_it_matters',v.student_content->>'whyItMatters','question',v.student_content->>'question')));
update private.class_material_versions v set student_content=v.student_content || jsonb_build_object('title',u.value->>'title','sparkText',u.value->>'spark_text','whyItMatters',u.value->>'why_it_matters','question',u.value->>'question')
from standalone_spark_version_updates u where u.id=v.id;
update public.class_assignments a set title=u.value->>'title' from standalone_spark_version_updates u where a.version_id=u.id;
commit;
